	app.Flags = append(app.Flags, FlagDef{Name: name, Description: desc, DefaultValue: dv, Required: false, Kind: FlagKindBool, Aliases: make([]string, 0)})
	app.lastFlagName = name
	app.lastFlagGlobal = false
	return app
